import sys

def main():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    t = int(next(it))
    answers = []
    for _ in range(t):
        n = int(next(it))
        carry = 0
        for _ in range(n):
            x = int(next(it))
            if carry > x:
                carry += x
            else:
                carry = x
        answers.append(str(carry))
    sys.stdout.write("\n".join(answers))

if __name__ == "__main__":
    main()
